// Le pattern Strategy : on place le "comportement qui varie" (ici le calcul du prix)
// derrière une interface, et on l'INJECTE dans la classe qui s'en sert.

interface PricingStrategy {
    long price(Cart cart); // chaque politique de prix implémentera cette méthode
}

// Une implémentation : prix standard.
class StandardPricing implements PricingStrategy {
    public long price(Cart cart) { return cart.subtotal(); }
}

// Une autre : promo -20 %.
class PromoPricing implements PricingStrategy {
    public long price(Cart cart) { return cart.subtotal() * 80 / 100; }
}

class Checkout {
    private final PricingStrategy pricing;              // Checkout ne connaît QUE l'interface
    Checkout(PricingStrategy pricing) { this.pricing = pricing; } // on injecte la stratégie
    long total(Cart cart) { return pricing.price(cart); }
}

// On change la stratégie (standard, promo, membre) sans TOUCHER au code de Checkout :
//   new Checkout(new PromoPricing()).total(cart);
